        if (!str) return '';
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&apos;');
    }

    static generateID() {
        return `_${crypto.randomBytes(21).toString('hex')}`;
    }

    static formatDate(date) {
        return date.toISOString();
    }

    static getCurrentTimestamp() {
        return this.formatDate(new Date());
    }

